test('webhook-out: subscriptions, secret on create, detail with deliveries, rotate, test, replay, deliveries, events, delete (audited)', async () => {
  const { cookie } = await signIn(t);
  const viewer = await signIn(t, { username: 'viewer5', role: 'viewer' });
  seen.length = 0;
  let res = await t.app.inject({ url: '/api/services/webhooks/atc-webhook-out/subscriptions?status=active&q=kargo', headers: { cookie } });
  assert.equal(res.statusCode, 200, res.body);
  assert.equal(res.json().items[0].name, 'kargocu-a');
  assert.equal(seen.at(-1)?.url, '/v1/subscriptions?q=kargo&status=active');
  assert.equal(seen.at(-1)?.headers.authorization, `Bearer ${'h'.repeat(40)}`, 'webhook-out key injected');
  const sub = { name: 'muhasebe', url: 'https://api.partner.example/acc', events: ['invoice.*'], headers: { 'X-Tenant': 'a' } };
  assert.equal((await t.app.inject({ method: 'POST', url: '/api/services/webhooks/atc-webhook-out/subscriptions', headers: { cookie: viewer.cookie, ...CSRF }, payload: sub })).statusCode, 403);
  res = await t.app.inject({ method: 'POST', url: '/api/services/webhooks/atc-webhook-out/subscriptions', headers: { cookie, ...CSRF }, payload: sub });
  assert.equal(res.statusCode, 201, res.body);
  assert.equal(res.json().secret, 'whsec_x', 'secret passed through once');
  assert.equal((await t.app.inject({ method: 'POST', url: '/api/services/webhooks/atc-webhook-out/subscriptions', headers: { cookie, ...CSRF }, payload: { ...sub, secret: 'mine' } })).statusCode, 400, 'unknown field');
  res = await t.app.inject({ url: '/api/services/webhooks/atc-webhook-out/subscriptions/sub_0000000000000001', headers: { cookie } });
  assert.equal(res.statusCode, 200, res.body);
  assert.deepEqual([res.json().subscription.name, res.json().deliveries.length, res.json().deliveriesNextBefore], ['kargocu-a', 2, null]);
  assert.equal(seen.at(-1)?.url, '/v1/deliveries?subscription=sub_0000000000000001&limit=20');
  assert.equal((await t.app.inject({ method: 'PATCH', url: '/api/services/webhooks/atc-webhook-out/subscriptions/sub_0000000000000001', headers: { cookie, ...CSRF }, payload: { enabled: false } })).json().subscription.status, 'paused');
  res = await t.app.inject({ method: 'POST', url: '/api/services/webhooks/atc-webhook-out/subscriptions/sub_0000000000000001/rotate', headers: { cookie, ...CSRF } });
  assert.equal(res.json().secret, 'whsec_new');
  res = await t.app.inject({ method: 'POST', url: '/api/services/webhooks/atc-webhook-out/subscriptions/sub_0000000000000001/test', headers: { cookie, ...CSRF } });
  assert.equal(res.statusCode, 202, res.body);
  res = await t.app.inject({ method: 'POST', url: '/api/services/webhooks/atc-webhook-out/subscriptions/sub_0000000000000001/replay', headers: { cookie, ...CSRF }, payload: { from: '2026-09-17T08:00:00Z' } });
  assert.equal(res.statusCode, 202, res.body);
  assert.equal(res.json().queued, 3);
  res = await t.app.inject({ url: '/api/services/webhooks/atc-webhook-out/deliveries?status=failed&subscription=sub_0000000000000001&limit=10', headers: { cookie } });
  assert.equal(seen.at(-1)?.url, '/v1/deliveries?status=failed&subscription=sub_0000000000000001&limit=10');
  assert.equal(res.json().items.length, 2);
  assert.equal((await t.app.inject({ url: '/api/services/webhooks/atc-webhook-out/deliveries/8', headers: { cookie: viewer.cookie } })).json().delivery.status, 'retrying');
  assert.equal((await t.app.inject({ method: 'POST', url: '/api/services/webhooks/atc-webhook-out/deliveries/8/redeliver', headers: { cookie: viewer.cookie, ...CSRF } })).statusCode, 403);
  assert.equal((await t.app.inject({ method: 'POST', url: '/api/services/webhooks/atc-webhook-out/deliveries/8/redeliver', headers: { cookie, ...CSRF } })).json().delivery.id, 10);
  assert.equal((await t.app.inject({ method: 'POST', url: '/api/services/webhooks/atc-webhook-out/deliveries/8/cancel', headers: { cookie, ...CSRF } })).json().delivery.status, 'cancelled');
  res = await t.app.inject({ url: '/api/services/webhooks/atc-webhook-out/events?type=order.paid&limit=5', headers: { cookie } });
  assert.equal(seen.at(-1)?.url, '/v1/events?type=order.paid&limit=5');
  assert.equal(res.json().items[0].id, 'evt_0000000000000001');
  assert.equal((await t.app.inject({ url: '/api/services/webhooks/atc-webhook-out/events/evt_0000000000000001', headers: { cookie } })).json().deliveries.length, 1);
  assert.equal((await t.app.inject({ url: '/api/services/webhooks/atc-webhook-out/event-types', headers: { cookie } })).json().items[0].type, 'order.paid');
  assert.equal((await t.app.inject({ url: '/api/services/webhooks/atc-webhook-out/stats', headers: { cookie } })).json().subscriptions.active, 4);
  assert.equal((await t.app.inject({ method: 'DELETE', url: '/api/services/webhooks/atc-webhook-out/subscriptions/sub_0000000000000001', headers: { cookie, ...CSRF } })).statusCode, 204);
  const log = await t.app.inject({ url: '/api/audit?action=atc-webhook-out.', headers: { cookie } });
  assert.deepEqual(log.json().items.map((/** @type {any} */ e) => e.action).slice(0, 8), ['atc-webhook-out.subscription.delete', 'atc-webhook-out.delivery.cancel', 'atc-webhook-out.delivery.redeliver', 'atc-webhook-out.subscription.replay', 'atc-webhook-out.subscription.test', 'atc-webhook-out.subscription.rotate', 'atc-webhook-out.subscription.update', 'atc-webhook-out.subscription.create']);
  assert.deepEqual(log.json().items[3].meta, { service: 'webhooks', from: '2026-09-17T08:00:00Z', queued: 3 });
  assert.equal((await t.app.inject({ url: '/api/services/atc-flags/atc-webhook-out/subscriptions', headers: { cookie } })).statusCode, 404, 'wrong service type');
});

